    if (!bridge) {
        return outerNode;
    }
    Node* bridgeReverse = splitPolygon(bridge, hole);
    // filter collinear points around the cuts
    filterPoints(bridgeReverse, bridgeReverse->next);   // bridgeReverse FIRST (order flipped vs A)
    return filterPoints(bridge, bridge->next);          // return value becomes new outerNode
