template <typename Polygon>
Node* eliminateHoles(const Polygon& points, Node* outerNode) {
    const size_t len = points.size();
    queue.clear();                                  // `queue` is a MEMBER std::vector<Node*>
    for (size_t i = 1; i < len; i++) {
        Node* list = linkedList(points[i], false);
        if (list) {
            if (list == list->next) list->steiner = true;
            queue.push_back(getLeftmost(list));
        }
    }
    std::sort(queue.begin(), queue.end(),
              [](const Node* a, const Node* b) { return a->x < b->x; });
    for (size_t i = 0; i < queue.size(); i++)       // queue.size() RE-READ each iteration
        outerNode = eliminateHole(queue[i], outerNode);
    return outerNode;
}

// ===== VARIANT A (OLD: earcut.hpp ~2.0-2.1.x) — REFUTED =====
bool isValidDiagonal(Node* a, Node* b) {
    return a->next->i != b->i && a->prev->i != b->i &&
           !intersectsPolygon(a, b) &&
           locallyInside(a, b) && locallyInside(b, a) &&
           middleInside(a, b);
}

// ===== VARIANT B (NEW: 2.2.x) — *** THIS IS THE REFERENCE *** =====
bool isValidDiagonal(Node* a, Node* b) {
