//   9. equals(a,b) && area(a->prev,a,a->next) > 0 && area(b->prev,b,b->next) > 0  (0x404380..0x40442b)

// ===== VARIANT A (OLD: earcut.hpp 2.0.x / 2.1.x, JS <2.2.0) — REFUTED =====
bool intersects(const Node* p1, const Node* q1, const Node* p2, const Node* q2) {
    if ((equals(p1, q1) && equals(p2, q2)) ||
        (equals(p1, q2) && equals(p2, q1))) return true;
    return (area(p1, q1, p2) > 0) != (area(p1, q1, q2) > 0) &&
           (area(p2, q2, p1) > 0) != (area(p2, q2, q1) > 0);
}

// ===== VARIANT B (NEW: 2.2.x) — *** THIS IS THE REFERENCE *** =====
int sign(double val) { return (0.0 < val) - (val < 0.0); }

bool onSegment(const Node* p, const Node* q, const Node* r) {
    return q->x <= std::max<double>(p->x, r->x) &&
           q->x >= std::min<double>(p->x, r->x) &&
           q->y <= std::max<double>(p->y, r->y) &&
           q->y >= std::min<double>(p->y, r->y);
}

bool intersects(const Node* p1, const Node* q1, const Node* p2, const Node* q2) {
    int o1 = sign(area(p1, q1, p2));
    int o2 = sign(area(p1, q1, q2));
    int o3 = sign(area(p2, q2, p1));
    int o4 = sign(area(p2, q2, q1));

    if (o1 != o2 && o3 != o4) return true;                        // general case
    if (o1 == 0 && onSegment(p1, p2, q1)) return true;            // p1,q1,p2 collinear and p2 on p1q1
    if (o2 == 0 && onSegment(p1, q2, q1)) return true;            // p1,q1,q2 collinear and q2 on p1q1
    if (o3 == 0 && onSegment(p2, p1, q2)) return true;            // p2,q2,p1 collinear and p1 on p2q2
    if (o4 == 0 && onSegment(p2, q1, q2)) return true;            // p2,q2,q1 collinear and q1 on p2q2
    return false;
}
// area(p,q,r) is ALWAYS: (q->y - p->y) * (r->x - q->x) - (q->x - p->x) * (r->y - q->y)

// ===== VARIANT A (OLD, no early return) — REFUTED =====
//   ... if (x <= hx && x > qx) { qx = x; m = p->x < p->next->x ? p : p->next; }
//   (loop always runs to completion; ties resolved only by `x > qx`)

// ===== VARIANT B — *** THIS IS THE REFERENCE *** =====
Node* findHoleBridge(Node* hole, Node* outerNode) {
    const Node* p = outerNode;
    double hx = hole->x;
    double hy = hole->y;
    double qx = -std::numeric_limits<double>::infinity();   // literal -inf (0xfff0000000000000), NOT -DBL_MAX
    Node* m = nullptr;

    // find a segment intersected by a ray from the hole's leftmost point to the left;
    // segment's endpoint with lesser x will be potential connection point
    do {
        if (hy <= p->y && hy >= p->next->y && p->next->y != p->y) {
            double x = p->x + (hy - p->y) * (p->next->x - p->x) / (p->next->y - p->y);
            //          ^ multiply FIRST, then divide, then add p->x. Confirmed 0x403da7-0x403dc8.
            if (x <= hx && x > qx) {
                qx = x;
                m = (p->x < p->next->x) ? const_cast<Node*>(p) : p->next;
                if (x == hx) return m;   // <<< PRESENT. hole touches outer segment; pick leftmost endpoint
            }
        }
        p = p->next;
    } while (p != outerNode);

    if (!m) return nullptr;
    ... // second loop, see next entry
}

// ===== second loop — *** REFERENCE ***, note the C++/JS divergence flagged below =====
    const Node* stop = m;
    double mx = m->x;
    double my = m->y;
    double tanMin = std::numeric_limits<double>::infinity();
    p = m;
    do {
        if (hx >= p->x && p->x >= mx && hx != p->x &&
            pointInTriangle(hy < my ? hx : qx, hy,
                            mx,                my,
                            hy < my ? qx : hx, hy,
                            p->x,              p->y)) {

