                m = const_cast<Node*>(p);
                tanMin = tan;
            }
        }
        p = p->next;
    } while (p != stop);
    return m;

// *** DIVERGENCE: modern JS (2.2.4 / 3.x) has an EXTRA guard here:
//        (p.x > m.x || (p.x === m.x && sectorContainsSector(m, p)))
//     The C++ port (and this reference binary) has NO `p->x == m->x &&`.
//     Verified: 0x403fad `ja` (p.x > m.x) falls straight through to the
//     sectorContainsSector code at 0x403fb3 with no intervening compare.

bool sectorContainsSector(const Node* m, const Node* p) {
    return area(m->prev, m, p->prev) < 0 && area(p->next, m, m->next) < 0;
}

Node* getLeftmost(Node* start) {
    Node* p = start;
    Node* leftmost = start;
    do {
        if (p->x < leftmost->x || (p->x == leftmost->x && p->y < leftmost->y))
            leftmost = p;                                  // y tie-break PRESENT
        p = p->next;
    } while (p != start);
    return leftmost;
}

// *** REFERENCE ***: isEar has NO bbox. isEarHashed HAS a bbox, used ONLY to derive the z range.
bool pointInTriangle(double ax,double ay,double bx,double by,double cx,double cy,double px,double py) {
    return (cx - px) * (ay - py) >= (ax - px) * (cy - py) &&
           (ax - px) * (by - py) >= (bx - px) * (ay - py) &&
           (bx - px) * (cy - py) >= (cx - px) * (by - py);   // all three are >=
}

bool isEar(Node* ear) {
    const Node* a = ear->prev;
    const Node* b = ear;
    const Node* c = ear->next;
    if (area(a, b, c) >= 0) return false;      // reflex, can't be an ear
    // NO bounding-box test here in 2.x
    Node* p = ear->next->next;
    while (p != ear->prev) {
        if (pointInTriangle(a->x,a->y, b->x,b->y, c->x,c->y, p->x,p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->next;
    }
    return true;
}

bool isEarHashed(Node* ear) {
    const Node* a = ear->prev;
    const Node* b = ear;
    const Node* c = ear->next;
    if (area(a, b, c) >= 0) return false;
    // triangle bbox; min & max are calculated like this for speed
    const double minTX = std::min<double>(a->x, std::min<double>(b->x, c->x));
    const double minTY = std::min<double>(a->y, std::min<double>(b->y, c->y));
    const double maxTX = std::max<double>(a->x, std::max<double>(b->x, c->x));
    const double maxTY = std::max<double>(a->y, std::max<double>(b->y, c->y));
    const int32_t minZ = zOrder(minTX, minTY);   // computed FIRST
    const int32_t maxZ = zOrder(maxTX, maxTY);   // computed SECOND

    Node* p = ear->nextZ;
    while (p && p->z <= maxZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x,a->y, b->x,b->y, c->x,c->y, p->x,p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->nextZ;
    }
    p = ear->prevZ;
    while (p && p->z >= minZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x,a->y, b->x,b->y, c->x,c->y, p->x,p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->prevZ;
    }
    return true;
}

// ===== JS 3.0 ONLY (do NOT implement) =====
//   isEar gains an explicit x0/y0/x1/y1 bbox membership test, and BOTH isEar and
//   isEarHashed switch to pointInTriangleExceptFirst(...) =
//       !(ax === px && ay === py) && pointInTriangle(...)
//   and isEarHashed drops the `p !== ear.prev && p !== ear.next` guards.

// ===== VARIANT A (OLD: 2.0.x / 2.1.x — store `size`, divide inside zOrder) — REFUTED =====
//   size = std::max<double>(maxX - minX, maxY - minY);
//   int32_t x = static_cast<int32_t>(32767.0 * (x_ - minX) / size);
//   int32_t y = static_cast<int32_t>(32767.0 * (y_ - minY) / size);

// ===== VARIANT B (NEW: 2.2.x) — *** THIS IS THE REFERENCE *** =====
int32_t zOrder(const double x_, const double y_) {
    // coords are transformed into non-negative 15-bit integer range
    int32_t x = static_cast<int32_t>((x_ - minX) * inv_size);   // MULTIPLY by precomputed reciprocal
    int32_t y = static_cast<int32_t>((y_ - minY) * inv_size);

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    return x | (y << 1);
}

// operator() — *** REFERENCE ***, exact order of operations:
void operator()(const Polygon& points) {
    indices.clear();
    vertices = 0;
    if (points.empty()) return;

    int threshold = 80;
    std::size_t len = 0;
    for (size_t i = 0; threshold >= 0 && i < points.size(); i++) {
        threshold -= static_cast<int>(points[i].size());   // short-circuits => `len` under-counts, harmless
        len += points[i].size();
    }
    nodes.reset(len * 3 / 2);
    indices.reserve(len + points[0].size());

    Node* outerNode = linkedList(points[0], true);
    if (!outerNode || outerNode->prev == outerNode->next) return;
    // *** NO filterPoints(outerNode, ...) here ***

    if (points.size() > 1) outerNode = eliminateHoles(points, outerNode);

    hashing = threshold < 0;
    if (hashing) {
        Node* p = outerNode->next;
        minX = maxX = outerNode->x;
        minY = maxY = outerNode->y;
        do {
            double x = p->x, y = p->y;
            minX = std::min<double>(minX, x);
            minY = std::min<double>(minY, y);
            maxX = std::max<double>(maxX, x);
            maxY = std::max<double>(maxY, y);
            p = p->next;
        } while (p != outerNode);
        inv_size = std::max<double>(maxX - minX, maxY - minY);
        inv_size = (inv_size != 0.0) ? (32767.0 / inv_size) : 0.0;
    }

    earcutLinked(outerNode, 0);
    nodes.clear();
}

// *** REFERENCE *** — no variant found; push order has been prev, ear, next throughout 2.x
void earcutLinked(Node* ear, int pass) {
    if (!ear) return;

    // interlink polygon nodes in z-order
    if (!pass && hashing) indexCurve(ear);

    Node* stop = ear;

    // iterate through ears, slicing them one by one
    while (ear->prev != ear->next) {
        Node* prev = ear->prev;
        Node* next = ear->next;

        if (hashing ? isEarHashed(ear) : isEar(ear)) {
            indices.emplace_back(prev->i);   // 1st
            indices.emplace_back(ear->i);    // 2nd
            indices.emplace_back(next->i);   // 3rd

            removeNode(ear);

            // skipping the next vertex leads to less sliver triangles
            ear  = next->next;
            stop = next->next;
            continue;
        }

        ear = next;

        if (ear == stop) {
            if (!pass)          earcutLinked(filterPoints(ear, nullptr), 1);
            else if (pass == 1) { ear = cureLocalIntersections(filterPoints(ear, nullptr));
                                  earcutLinked(ear, 2); }
            else if (pass == 2) splitEarcut(ear);
            break;
        }
    }
}

void removeNode(Node* p) {
    p->next->prev = p->prev;
    p->prev->next = p->next;
    if (p->prevZ) p->prevZ->nextZ = p->nextZ;
    if (p->nextZ) p->nextZ->prevZ = p->prevZ;
}

// ===== VARIANT A (OLD, some 2.0.x): final line was `return p;` (no filterPoints) — LOW CONFIDENCE
// ===== VARIANT B — *** THIS IS THE REFERENCE *** =====
Node* cureLocalIntersections(Node* start) {
    Node* p = start;
    do {
        Node* a = p->prev;
        Node* b = p->next->next;

        // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
        if (!equals(a, b) && intersects(a, p, p->next, b) &&
            locallyInside(a, b) && locallyInside(b, a)) {

            indices.emplace_back(a->i);
            indices.emplace_back(p->i);
            indices.emplace_back(b->i);

            removeNode(p);
            removeNode(p->next);   // p->next re-read AFTER removeNode(p); removeNode does not touch p->next

            p = start = b;
        }
        p = p->next;
    } while (p != start);

    return filterPoints(p, nullptr);
}

bool equals(const Node* p1, const Node* p2) { return p1->x == p2->x && p1->y == p2->y; }

// *** ALL REFERENCE FORMS — verified against the binary ***
template <typename Ring>
Node* linkedList(const Ring& points, const bool clockwise) {
    double sum = 0;
    const std::size_t len = points.size();
    Node* last = nullptr;

    // calculate original winding order of a polygon ring
    for (std::size_t i = 0, j = (len > 0 ? len - 1 : 0); i < len; j = i++) {
        const double p10 = x(points[i]), p11 = y(points[i]);
        const double p20 = x(points[j]), p21 = y(points[j]);
        sum += (p20 - p10) * (p11 + p21);
    }

    // link points into circular doubly-linked list in the specified winding order
    if (clockwise == (sum > 0)) {
        for (std::size_t i = 0; i < len; i++)  last = insertNode(vertices + i, points[i], last);
    } else {
        for (std::size_t i = len; i-- > 0;)    last = insertNode(vertices + i, points[i], last);
    }

    if (last && equals(last, last->next)) {   // drop a duplicated closing vertex
        removeNode(last);
        last = last->next;
    }
    vertices += len;
    return last;                              // NOTE: returns the LAST inserted node
}

Node* splitPolygon(Node* a, Node* b) {
    Node* a2 = nodes.construct(a->i, a->x, a->y);   // a2 constructed FIRST
    Node* b2 = nodes.construct(b->i, b->x, b->y);   // b2 SECOND
    Node* an = a->next;
    Node* bp = b->prev;
    a->next = b;   b->prev = a;
    a2->next = an; an->prev = a2;
    b2->next = a2; a2->prev = b2;
    bp->next = b2; b2->prev = bp;
    return b2;
}

Node* filterPoints(Node* start, Node* end) {
    if (!end) end = start;
    Node* p = start;
    bool again;
    do {
        again = false;
        if (!p->steiner && (equals(p, p->next) || area(p->prev, p, p->next) == 0)) {
            removeNode(p);
            p = end = p->prev;
            if (p == p->next) break;
            again = true;
        } else {
            p = p->next;
        }
    } while (again || p != end);
    return end;
}

// *** ALL REFERENCE FORMS ***
bool locallyInside(const Node* a, const Node* b) {
    return area(a->prev, a, a->next) < 0
        ? (area(a, b, a->next) >= 0 && area(a, a->prev, b) >= 0)
        : (area(a, b, a->prev) < 0  || area(a, a->next, b) < 0);
}

bool middleInside(const Node* a, const Node* b) {
    const Node* p = a;
    bool inside = false;
    double px = (a->x + b->x) / 2;
    double py = (a->y + b->y) / 2;
    do {
        if (((p->y > py) != (p->next->y > py)) && p->next->y != p->y &&
            (px < (p->next->x - p->x) * (py - p->y) / (p->next->y - p->y) + p->x))
            inside = !inside;
        p = p->next;
    } while (p != a);
    return inside;
}

bool intersectsPolygon(const Node* a, const Node* b) {
    const Node* p = a;
    do {
        if (p->i != a->i && p->next->i != a->i && p->i != b->i && p->next->i != b->i &&
            intersects(p, p->next, a, b)) return true;
        p = p->next;
    } while (p != a);
    return false;
}

